import assert from 'node:assert/strict'
import { spawn, execFileSync } from 'node:child_process'
import { existsSync, rmSync, writeFileSync } from 'node:fs'

const PROD='https://osrm.github.io/catfood_web/'
const PREVIEW='http://127.0.0.1:4173/'
const PROD_SHA='41346569f410d8caf9540f5e7be04a1de9847ec9'
const PR_SHA='bdc162783f28653904939913dca1dd9584f32c95'
const TARGET='Pacific Catch'
const sleep=(ms)=>new Promise((r)=>setTimeout(r,ms))

class Cdp{constructor(url){this.url=url;this.ws=null;this.id=1;this.pending=new Map()}async connect(){this.ws=new WebSocket(this.url);await new Promise((res,rej)=>{const t=setTimeout(()=>rej(new Error('ws timeout')),15000);this.ws.addEventListener('open',()=>{clearTimeout(t);res()},{once:true});this.ws.addEventListener('error',()=>rej(new Error('ws error')),{once:true})});this.ws.addEventListener('message',(e)=>{const m=JSON.parse(e.data);if(!m.id)return;const p=this.pending.get(m.id);if(!p)return;this.pending.delete(m.id);m.error?p.reject(new Error(m.error.message)):p.resolve(m.result)});for(const m of ['Page.enable','Runtime.enable'])await this.send(m)}send(method,params={}){const id=this.id++;return new Promise((res,rej)=>{this.pending.set(id,{resolve:res,reject:rej});this.ws.send(JSON.stringify({id,method,params}))})}async eval(expression){const r=await this.send('Runtime.evaluate',{expression,returnByValue:true,awaitPromise:true});if(r.exceptionDetails)throw new Error(r.exceptionDetails.exception?.description||r.exceptionDetails.text);return r.result?.value}async wait(expression,label,ms=45000){const end=Date.now()+ms;while(Date.now()<end){try{if(await this.eval(`Boolean(${expression})`))return}catch{}await sleep(120)}throw new Error(`timeout ${label}`)}async nav(url){await this.send('Page.navigate',{url});await this.wait(`document.readyState==='complete'`,'ready');await this.wait(`document.querySelector('#root')&&document.body.innerText.length>0`,'root')}async viewport(w,h){await this.send('Emulation.setDeviceMetricsOverride',{width:w,height:h,deviceScaleFactor:1,mobile:false})}async shot(path){const r=await this.send('Page.captureScreenshot',{format:'png',fromSurface:true,captureBeyondViewport:false});writeFileSync(path,Buffer.from(r.data,'base64'))}close(){try{this.ws?.close()}catch{}}}
async function launch(){const bin='/usr/bin/google-chrome';assert.ok(existsSync(bin));const version=execFileSync(bin,['--version'],{encoding:'utf8'}).trim();const port=9920+(process.pid%50);const dir=`/tmp/catfood-switch-pr18-${process.pid}`;rmSync(dir,{recursive:true,force:true});const proc=spawn(bin,['--headless=new','--no-sandbox','--disable-dev-shm-usage','--disable-gpu',`--remote-debugging-port=${port}`,`--user-data-dir=${dir}`,'about:blank'],{stdio:'ignore'});for(let i=0;i<200;i++){try{const pages=await(await fetch(`http://127.0.0.1:${port}/json/list`)).json();const p=pages.find(x=>x.type==='page'&&x.webSocketDebuggerUrl);if(p)return{version,proc,dir,c:new Cdp(p.webSocketDebuggerUrl)}}catch{}await sleep(100)}throw new Error('chrome start timeout')}
async function clickText(c,selector,text){const ok=await c.eval(`(()=>{const n=[...document.querySelectorAll(${JSON.stringify(selector)})].find(x=>x.textContent?.includes(${JSON.stringify(text)}));if(!n)return false;n.scrollIntoView({block:'center'});n.click();return true})()`);assert.ok(ok,`missing click target: ${text}`);await sleep(180)}
async function setInput(c,selector,value){const ok=await c.eval(`(()=>{const n=document.querySelector(${JSON.stringify(selector)});if(!n)return false;const s=Object.getOwnPropertyDescriptor(HTMLInputElement.prototype,'value').set;s.call(n,${JSON.stringify(value)});n.dispatchEvent(new Event('input',{bubbles:true}));return true})()`);assert.ok(ok,`missing input ${selector}`);await sleep(250)}
async function openTargetCandidate(c){for(let i=0;i<25;i++){const found=await c.eval(`[...document.querySelectorAll('.switch-candidate-row')].some(x=>x.textContent?.includes(${JSON.stringify(TARGET)}))`);if(found){await clickText(c,'.switch-candidate-row',TARGET);return}const more=await c.eval(`Boolean(document.querySelector('.switch-candidate-list .load-more'))`);if(!more)break;await clickText(c,'.switch-candidate-list .load-more','제품 더 보기')}throw new Error('target candidate not found')}
async function reachInspector(c,base,prefix){await c.viewport(1440,1000);await c.nav(base+'?view=workspace&mode=switch');await c.wait(`document.querySelector('.switch-find-search input')`,'switch search');await setInput(c,'.switch-find-search input','로얄캐닌');await c.wait(`document.querySelectorAll('.switch-find-result').length>0`,'current results');await c.eval(`document.querySelector('.switch-find-result')?.click()`);await c.wait(`document.querySelector('.switch-current-preview')`,'current preview');await clickText(c,'.switch-current-preview button','이 제품을 현재 사료로 선택');await c.wait(`document.querySelector('.switch-sku-list')`,'sku');await clickText(c,'.switch-step-actions button','사용 규격을 모르겠어요');await c.wait(`[...document.querySelectorAll('h1')].some(x=>x.textContent?.includes('무엇을 바꾸고 싶나요'))`,'change step');await clickText(c,'button','특별히 바꾸고 싶은 점 없음');await clickText(c,'.switch-step-actions button','다음');await c.wait(`[...document.querySelectorAll('h1')].some(x=>x.textContent?.includes('무엇을 그대로 유지할까요'))`,'keep step');await clickText(c,'.switch-step-actions button','후보 제품 보기');await c.wait(`document.querySelector('.switch-candidate-list')`,'candidate results');await openTargetCandidate(c);await c.wait(`document.querySelector('.switch-candidate-inspector')`,'candidate inspector');const value=await c.eval(`(()=>{const dt=[...document.querySelectorAll('.switch-candidate-inspector dt')].find(x=>x.textContent?.trim()==='세부 레시피');if(!dt)return null;const dd=dt.parentElement?.querySelector('dd');dt.parentElement?.scrollIntoView({block:'center'});return dd?.textContent?.trim()||null})()`);assert.ok(value,'recipe detail value missing');await sleep(180);await c.shot(`qa-artifacts/${prefix}-switch-pacific-catch.png`);return{value,url:await c.eval('location.href')}}

const {version,proc,dir,c}=await launch();const report={browserVersion:version,production:{sha:PROD_SHA,base:PROD},candidate:{sha:PR_SHA,base:PREVIEW},target:TARGET}
try{await c.connect();const before=await reachInspector(c,PROD,'before-prod-41346569');const after=await reachInspector(c,PREVIEW,'after-pr-bdc16278');assert.ok(before.value.includes('hoki'),'production does not show expected raw fallback');assert.ok(after.value.includes('호키'),'candidate missing Korean label');assert.ok(!after.value.includes('hoki'),'candidate still exposes raw hoki fallback');writeFileSync('qa-artifacts/report.json',JSON.stringify({...report,before,after},null,2));console.log('SWITCH_RECIPE_LABEL_QA PASS',before.value,'=>',after.value)}catch(e){writeFileSync('qa-artifacts/report.json',JSON.stringify({...report,error:String(e),url:await c.eval('location.href').catch(()=>null),screen:await c.eval('document.body.innerText').catch(()=>null)},null,2));await c.shot('qa-artifacts/failure-current-screen.png').catch(()=>{});throw e}finally{c.close();proc.kill('SIGTERM');await sleep(200);if(proc.exitCode==null)proc.kill('SIGKILL');rmSync(dir,{recursive:true,force:true})}
